//! Generated by Codex. State isolation and budgets on the real component path.
use super::*;
use crate::service::invocation_limits::InvocationLimits;
use crate::service::invocation_test_component::component;

#[test]
#[cfg_attr(miri, ignore)]
fn globals_and_memory_do_not_leak_between_requests() {
    let pre = component(
        "global.get $counter i32.const 1 i32.add global.set $counter i32.const 16 global.get $counter i32.store8",
    );
    for _ in 0..3 {
        let mut lease = pre.lease_sync("mp2-test").unwrap();
        let inner = lease.inner.as_mut().unwrap();
        let (bytes,) = inner.typed_func.call(&mut inner.store, (vec![],)).unwrap();
        assert_eq!(bytes, vec![1]);
    }
    assert_eq!(pre.pool_idle_len("mp2-test"), 0);
}

#[test]
#[cfg_attr(miri, ignore)]
fn real_component_loop_and_growth_are_stopped() {
    for body in ["(loop br 0)", "i32.const 100 memory.grow drop"] {
        let pre = component(body);
        let control = InvocationContext::new(InvocationLimits {
            memory_bytes: 65536,
            fuel: 1000,
            ..Default::default()
        })
        .unwrap();
        let mut lease = pre
            .lease_sync_with_context("mp2-test", control, None)
            .unwrap();
        let inner = lease.inner.as_mut().unwrap();
        assert!(inner.typed_func.call(&mut inner.store, (vec![],)).is_err());
    }
}
